std::vector<int> data = {1, 2, 3};

auto start = data.begin();
auto stop = data.end();

// Iterate and dereference
while (start != stop) {
    std::cout << *start;
    ++start;
}

// Generic algorithms often take iterator pairs
std::sort(data.begin(), data.end());

// ---

std::vector<int> v(10);
auto it = v.begin();

// Iterator arithmetic (Random Access Iterators only)
it += 5;
int distance = it - v.begin();

// Generic advance/next functions
auto second = std::next(v.begin());
std::advance(it, -3); // it moves backwards by 3

// ---

std::list<int> l = {1, 2, 3};

// Const iteration (cbegin/cend)
for (auto cit = l.cbegin(); cit != l.cend(); ++cit) {
    std::cout << *cit;
}

// Reverse iteration (rbegin/rend)
for (auto rit = l.rbegin(); rit != l.rend(); ++rit) {
    std::cout << *rit;
}
